1	using System;
2	using System.Collections.Generic;
3	using System.IO;
4	using System.Linq;
5	using System.Text.RegularExpressions;
6	using MonoDreams.Platform;
7	using MonoDreams.State;
8	using Xunit;
9	
10	namespace MonoDreams.Tests.Foundation;
11	
12	/// <summary>
13	/// Protects the <see cref="Logger"/> interpolated-string-handler seam (issue #37): a log line at a
14	/// suppressed level must cost nothing — the interpolation holes are never evaluated — while an
15	/// enabled line stays byte-identical to what the plain <c>string</c> overload has always produced.
16	/// Both halves matter: the first is the whole point of the handler, the second is why nobody has to
17	/// audit 300+ call sites after it lands.
18	///
19	/// The tests drive a fake <see cref="IPlatformServices"/> so both sinks (the log writer and the
20	/// console echo) are observable with no real disk. <see cref="Logger"/> and
21	/// <see cref="PlatformServices.Current"/> are process-global static state, so this class shares the
22	/// non-parallel collection with <c>PlatformServicesTests</c>, restores the desktop default in a
23	/// finally, and resets the logger's threshold on both sides of every test (see the ctor/Dispose
24	/// pair below).
25	/// </summary>
26	[Collection("PlatformServices (non-parallel: mutates static state)")]
27	public class LoggerInterpolationTests : IDisposable
28	{
29	    // xUnit builds one instance per test: the ctor runs before it and Dispose after it, so the
30	    // process-global Logger is returned to its default threshold on BOTH sides. That matters more
31	    // than usual now — `Shutdown` does not reset `MinimumLevel`, and leaving it at Warning/Error
32	    // would silently suppress (and, at an interpolated call site, skip the holes of) every later
33	    // test's log lines in this assembly.
34	    public LoggerInterpolationTests() => ResetLoggerStatics();
35	
36	    public void Dispose() => ResetLoggerStatics();
37	
38	    /// <summary>The format contract every emitted line must satisfy — the input-replay /
39	    /// verification workflow and the tooling greps parse it, so it is pinned here rather than
40	    /// left to reviewer memory.</summary>
41	    private const string FormatContract =
42	        @"^\[\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}\.\d{3}\] \[GT (  N/A |[ \d]+\.\d{2})\] \[(DEBUG| INFO| WARN|ERROR)\] ";
43	
44	    /// <summary>
45	    /// Minimal in-memory <see cref="IPlatformServices"/>: enough to capture the two Logger sinks.
46	    /// Mirrors the fake in <c>PlatformServicesTests</c>.
47	    /// </summary>
48	    private sealed class FakePlatformServices : IPlatformServices
49	    {
50	        public string BaseDirectory => "/fake/base/";
51	        public List<string> ConsoleLines { get; } = new();
52	        public List<string> CreatedDirectories { get; } = new();
53	        public StringWriter LogWriter { get; } = new();
54	
55	        // IPlatformServices is nullable-oblivious (the engine does not enable NRT); `null!` keeps
56	        // this nullable-enabled test assembly quiet without changing the contract.
57	        public string GetEnvironmentVariable(string name) => null!;
58	        public string CombinePath(params string[] paths) => string.Join("/", paths);
59	        public bool FileExists(string path) => false;
60	        public string ReadAllText(string path) => throw new FileNotFoundException(path);
61	        public void WriteAllText(string path, string contents) { }
62	        public void WriteAllBytes(string path, byte[] bytes) { }
63	        public string ExportScene(string suggestedFileName, string contents) => suggestedFileName;
64	        public void CreateDirectory(string path) => CreatedDirectories.Add(path);
65	
66	        public TextWriter OpenLogWriter(string directory, string fileName)
67	        {
68	            CreatedDirectories.Add(directory);
69	            return LogWriter;
70	        }
71	
72	        public void WriteLineToConsole(string line) => ConsoleLines.Add(line);
73	        public void RunBackground(Action work) => work();
74	    }
75	
76	    /// <summary>A hole the handler must never touch at a suppressed level: touching it throws.</summary>
77	    private sealed class Boom
78	    {
79	        public override string ToString() =>
80	            throw new InvalidOperationException("interpolation hole was evaluated at a suppressed level");
81	    }
82	
83	    private static void RunWithFake(FakePlatformServices fake, Action body)
84	    {
85	        var previous = PlatformServices.Current;
86	        try
87	        {
88	            PlatformServices.Current = fake;
89	            body();
90	        }
91	        finally
92	        {
93	            PlatformServices.Current = previous; // restore desktop default
94	        }
95	    }
96	
97	    /// <summary>
98	    /// <see cref="Logger"/> is process-global: <see cref="Logger.Initialize"/> is a no-op while an
99	    /// earlier session is still open, only <see cref="Logger.Shutdown"/> resets the game-time field
100	    /// behind <c>[GT ...]</c>, and nothing but a fresh <c>Initialize</c> resets
101	    /// <see cref="Logger.MinimumLevel"/>. An open-then-close pair on a throwaway sink therefore
102	    /// restores all three — closed, <c>[GT   N/A ]</c>, threshold back at <see cref="LogLevel.Debug"/>
103	    /// — whatever ran before. The sink is throwaway because <see cref="StringWriter"/> refuses
104	    /// writes once Shutdown disposed it.
105	    /// </summary>
106	    private static void ResetLoggerStatics()
107	    {
108	        RunWithFake(new FakePlatformServices(), () =>
109	        {
110	            Logger.Shutdown();
111	            Logger.Initialize("scratch");
112	            Logger.Shutdown();
113	        });
114	    }
115	
116	    /// <summary>Every line the two sinks saw, minus the Logger's own start/stop bookkeeping.</summary>
117	    private static List<string> EmittedLines(FakePlatformServices fake) =>
118	        fake.ConsoleLines
119	            .Where(l => !l.Contains("Logger initialized.") && !l.Contains("Logger shutting down."))
120	            .ToList();
121	
122	    private static string WithoutWallClock(string line) => Regex.Replace(line, @"^\[[^\]]+\] ", "");
123	
124	    // ─── (a) a suppressed level evaluates nothing ─────────────────────────────────────────────────
